(() => {
 'use strict';
 // Analytic teaching experiments, not MSC Nastran solver output or distributable decks.
 // Visible SVG text contains symbols/units only. Captions and controls are outside SVG.
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const fmt=(x,d=3)=>!Number.isFinite(x)?'—':Number(x.toPrecision(d)).toLocaleString('en-US',{maximumFractionDigits:7});
 const rad=a=>a*Math.PI/180, lin=(a,b,n=61)=>Array.from({length:n},(_,i)=>a+(b-a)*i/(n-1));
 const txt=(x,y,s,anchor='middle')=>`<text x="${x}" y="${y}" text-anchor="${anchor}">${esc(s)}</text>`;
 const line=(x1,y1,x2,y2,cls='el-edge')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" class="${cls}"/>`;
 const circle=(x,y,r=4,cls='el-node')=>`<circle cx="${x}" cy="${y}" r="${r}" class="${cls}"/>`;
 const arrow=(x1,y1,x2,y2,cls='el-force')=>{const dx=x2-x1,dy=y2-y1,l=Math.hypot(dx,dy);if(l<.001)return '';const ux=dx/l,uy=dy/l,h=Math.min(8,l*.6),w=h*.45;return line(x1,y1,x2-ux*h*.5,y2-uy*h*.5,cls)+`<polygon class="${cls}-head" points="${x2},${y2} ${x2-ux*h+uy*w},${y2-uy*h-ux*w} ${x2-ux*h-uy*w},${y2-uy*h+ux*w}"/>`;};
 const svg=(body,label,h=230)=>`<svg class="el-svg" viewBox="0 0 360 ${h}" role="img" aria-label="${esc(label)}">${body}</svg>`;
 const spring=(x1,y1,x2,y2,label)=>{const dx=x2-x1,dy=y2-y1,l=Math.hypot(dx,dy),ux=dx/l,uy=dy/l,pts=[[x1,y1]];for(let j=0;j<=12;j++){const a=.15+.7*j/12,b=j===0||j===12?0:(j%2?7:-7);pts.push([x1+dx*a-uy*b,y1+dy*a+ux*b]);}pts.push([x2,y2]);return `<polyline class="el-edge" points="${pts.map(p=>p.join(',')).join(' ')}"/>`+(label?txt((x1+x2)/2-uy*19,(y1+y2)/2+ux*19,label):'');};
 const ground=(x,y)=>line(x,y-19,x,y+19)+[0,1,2,3,4].map(i=>line(x,y-16+i*8,x-8,y-9+i*8)).join('');
 const slider=(id,label,min,max,step,value)=>`<label>${label}<input type="range" data-el-input="${id}" min="${min}" max="${max}" step="${step}" value="${value}"><output data-el-out="${id}"></output></label>`;
 const select=(id,label,opts,value)=>`<label>${label}<select data-el-input="${id}">${opts.map(([k,t])=>`<option value="${k}"${k===value?' selected':''}>${t}</option>`).join('')}</select></label>`;
 const layout=(controls,caption)=>`<div class="theory-lab-controls">${controls}</div><div class="el-plot"></div><div class="theory-lab-readout" aria-live="polite"></div><figcaption>${caption}</figcaption>`;
 const vals=o=>Object.fromEntries(Object.entries(o.inputs).map(([k,e])=>[k,e.type==='range'?+e.value:e.value]));
 const result=(el,html)=>el.read.innerHTML=html;
 const outputs=(el,v)=>Object.entries(v).forEach(([k,x])=>{if(el.out[k])el.out[k].textContent=fmt(x);});
 function chart(id,series,x,y,xl,yl){return window.BeamLabs.graphics.chart({id:'el-'+id,label:xl+' / '+yl,x,y,xt:lin(...x,5),yt:lin(...y,5),xf:v=>fmt(v),yf:v=>fmt(v),xl,yl,legend:true,series:series.map((s,i)=>({pts:s[1],name:s[0],strong:i===0,dash:['','7 4','2 4'][i%3]}))});}
 const vsub=(a,b)=>a.map((v,i)=>v-b[i]),cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],dot=(a,b)=>a.reduce((s,v,i)=>s+v*b[i],0);
 const avg=ps=>[0,1,2].map(i=>ps.reduce((s,p)=>s+p[i],0)/ps.length);
 function poly3(ps,faces=HEXF,rgb=[150,178,206]){const center=avg(ps);return faces.map(ids=>{let p=ids.map(i=>ps[i]),n=cross(vsub(p[1],p[0]),vsub(p[2],p[0]));if(dot(n,vsub(avg(p),center))<0)n=n.map(v=>-v);const len=Math.hypot(...n)||1;return {k:'face',p,n:n.map(v=>v/len),rgb,stroke:'#496580',sw:.8,two:true};});}
 const HEXF=[[0,1,2,3],[4,5,6,7],[0,1,5,4],[1,2,6,5],[2,3,7,6],[3,0,4,7]];
 const cube=(L=5,B=2,H=2)=>[[0,-B/2,-H/2],[L,-B/2,-H/2],[L,B/2,-H/2],[0,B/2,-H/2],[0,-B/2,H/2],[L,-B/2,H/2],[L,B/2,H/2],[0,B/2,H/2]];
 const ghost3=(ps,faces=HEXF)=>faces.map(ids=>({k:'line',p:[...ids,ids[0]].map(i=>ps[i]),c:'b3-ghost',back:true}));
 function strip3(L,B,H,transform){const items=[];for(let i=0;i<20;i++){const a=L*i/20,b=L*(i+1)/20,ps=cube(b-a,B,H).map(([x,y,z])=>transform(x+a,y,z)),faces=[HEXF[0],HEXF[1],HEXF[2],HEXF[4]];if(i===0)faces.push(HEXF[5]);if(i===19)faces.push(HEXF[3]);for(const f of poly3(ps,faces))items.push({...f,stroke:undefined,sw:.2});}return items;}
 const a3=(a,b,s)=>[{k:'arrow',p:[a,b],c:'b3-load'},...(s?[{k:'text',p:[b],s,c:'b3-loadText',dx:5,dy:-5}]:[])];
 const axes3=(o=[0,0,0],l=1)=>[0,1,2].flatMap(i=>{const b=o.map((v,j)=>v+(i===j?l:0));return [{k:'arrow',p:[o,b],c:'b3-axis'},{k:'text',p:[b],s:['x','y','z'][i],dx:5,dy:-3}];});
 const scene=(items,label,h=240)=>window.BeamLabs.graphics.render3d(items,{w:360,h,label,pad:28,cam:window.BeamLabs.graphics.camera(-50,24)});

 const core={
  spring:(k,u1,u2)=>({f1:k*(u1-u2),f2:-k*(u1-u2),energy:k*(u1-u2)**2/2}),
  network:(k1,k2,P,parallel)=>{const k=parallel?k1+k2:k1*k2/(k1+k2),u=P/k;return {k,u,q:parallel?u:P/k2,f1:parallel?k1*u:P,f2:parallel?k2*u:P};},
  direction:(k1,k2,deg,u=.5)=>{const c=Math.cos(rad(deg)),s=Math.sin(rad(deg)),xx=k1*c*c+k2*s*s,xy=(k1-k2)*c*s,yy=k1*s*s+k2*c*c;return {xx,xy,yy,Fx:xx*u,Fy:xy*u,energy:xx*u*u/2};},
  kelvin:(k,c,f,U=.5)=>({omega:2*Math.PI*f,elastic:k*U,viscous:c*2*Math.PI*f*U,loss:Math.PI*c*2*Math.PI*f*U*U}),
  surface:(N,M,t)=>({top:N/t+6*M/t**2,bottom:N/t-6*M/t**2,mean:N/t,bend:6*M/t**2}),
  material:(deg,isotropic=false)=>{const c=Math.cos(rad(deg)),s=Math.sin(rad(deg)),E1=isotropic?70000:140000,E2=isotropic?70000:10000,nu=.3,G=isotropic?70000/2.6:5000,stress=100,s1=stress*c*c,s2=stress*s*s,tau=-stress*c*s,e1=(s1-nu*s2)/E1,e2=s2/E2-nu*s1/E1,g=tau/G;return {s1,s2,tau,ex:c*c*e1+s*s*e2-c*s*g,ey:s*s*e1+c*c*e2+c*s*g,gxy:2*c*s*(e1-e2)+(c*c-s*s)*g};},
  quad:(x,y)=>{const ps=[[-1,-1],[1,-1],[x,y],[-1,1]],map=(r,s)=>{const N=[(1-r)*(1-s),(1+r)*(1-s),(1+r)*(1+s),(1-r)*(1+s)].map(n=>n/4);return [0,1].map(i=>ps.reduce((v,p,k)=>v+N[k]*p[i],0));},jac=(r,s)=>{const dr=[-(1-s),1-s,1+s,-(1+s)].map(v=>v/4),ds=[-(1-r),-(1+r),1+r,1-r].map(v=>v/4),a=[0,1].map(i=>ps.reduce((v,p,k)=>v+dr[k]*p[i],0)),b=[0,1].map(i=>ps.reduce((v,p,k)=>v+ds[k]*p[i],0));return a[0]*b[1]-a[1]*b[0];};return {ps,map,jac,min:Math.min(...[[-1,-1],[1,-1],[1,1],[-1,1]].map(p=>jac(...p)))};},
  sandwich:c=>({B:70000*(2/12+2*((c+1)/2)**2)+100*c**3/12,mass:(2*2700+100*c)/1000}),
  poisson:(nu,held)=>{const E=2000,sigma=10,ratio=(1-nu)/((1+nu)*(1-2*nu)),ex=sigma/E/(held?ratio:1);return {ex,ey:held?0:-nu*ex,ratio:held?ratio:1,sy:held?nu/(1-nu)*sigma:0,K:E/(3*(1-2*nu))};},
  interpolate:(x,n,quadratic)=>{if(quadratic)return {u:x*x,strain:2*x};const i=Math.min(n-1,Math.floor(x*n)),a=i/n,b=(i+1)/n;return {u:a*a+(x-a)*(a+b),strain:a+b};},
  couple:(M,h,n)=>{const z=Array.from({length:n},(_,i)=>i<n/2?h/2:-h/2),I=z.reduce((s,v)=>s+v*v,0);return z.map(v=>({z:v,F:M*v/I}));},
  tetra:(height,reverse=false)=>({det:(reverse?-1:1)*1e6*height,volume:1e6*Math.abs(height)/6,gradient:.01/height}),
  pressure:(p,tau)=>{const E=70000,nu=.3,K=E/(3*(1-2*nu)),G=E/(2*(1+nu));return {K,G,ev:-p/K,ex:-p/(3*K),gamma:tau/G,vm:Math.sqrt(3)*Math.abs(tau),principal:[-p+tau,-p,-p-tau]};},
  cylinder:(r,b,a=20,p=10,closed=false)=>{const A=p*a*a/(b*b-a*a),B=p*a*a*b*b/(b*b-a*a),sr=A-B/r**2,st=A+B/r**2,sz=closed?A:0;return {sr,st,sz,vm:Math.sqrt(((sr-st)**2+(st-sz)**2+(sz-sr)**2)/2)};}
 };
 const labs={};
 labs.relative={html:()=>layout(slider('k','K（N/mm）',20,200,10,100)+slider('a','u₁（mm）',-1,1,.1,.5)+slider('b','u₂（mm）',-1,1,.1,0)+select('ground','端2',[['free','変位を指定する'],['fixed','接地：u₂ = 0']],'free'),'記号の位置は自由度を区別するための図です。CELAS に実物の長さや断面を与える図ではありません。赤の矢印は指定変位を保つため外から加える力、破線は変位ゼロの位置。変位の描画倍率は一定です。'),draw(el,v){const b=v.ground==='fixed'?0:v.b,r=core.spring(v.k,v.a,b),x1=85+v.a*30,x2=260+b*30;el.inputs.b.disabled=v.ground==='fixed';el.plot.innerHTML=svg(line(85,45,85,155,'el-ghost')+line(260,45,260,155,'el-ghost')+spring(x1,100,x2,100,'K')+circle(x1,100)+circle(x2,100)+(v.ground==='fixed'?ground(x2+5,100):'')+txt(x1,150,'u₁ = '+fmt(v.a))+txt(x2,150,'u₂ = '+fmt(b))+arrow(x1,75,x1+Math.sign(r.f1)*36,75)+arrow(x2,75,x2+Math.sign(r.f2)*36,75)+txt(x1,49,'f₁')+txt(x2,49,'f₂')+txt(180,192,'Δu = u₁ − u₂'),'ばねの相対変位とつり合い');result(el,`Δu = <b>${fmt(v.a-b)} mm</b>、f₁ = <b>${fmt(r.f1)} N</b>、f₂ = <b>${fmt(r.f2)} N</b>。<br>蓄えられるエネルギー U = KΔu²/2 = ${fmt(r.energy)} N·mm。${v.ground==='fixed'?'未知変位は u₁ の1つ。端2の反力は消えません。':'u₁ と u₂ を同じだけ変えると、ばね力もエネルギーも変わりません。'}`);}};
 labs.network={html:()=>layout(select('kind','接続',[['series','直列：中間点は SPOINT'],['parallel','並列：両端の変位を共有']],'series')+slider('k1','K₁（N/mm）',20,200,10,120)+slider('k2','K₂（N/mm）',20,200,10,80)+slider('P','P（N）',0,100,5,48),'左端を地面、右端を GRID の選択した1成分とします。直列の中間点 q は座標を持たない SPOINT。横の位置は模式的で、点間距離をばね定数に使いません。'),draw(el,v){const par=v.kind==='parallel',r=core.network(v.k1,v.k2,v.P,par);let s=ground(35,105)+circle(315,105)+arrow(315,105,350,105)+txt(330,85,'P')+txt(310,152,'u');if(par){s+=line(35,60,35,140)+line(315,60,315,140)+spring(35,60,315,60,'K₁')+spring(35,140,315,140,'K₂');}else{s+=spring(35,105,175,105,'K₂')+spring(175,105,315,105,'K₁')+circle(175,105)+txt(175,78,'SPOINT 20')+txt(175,153,'q');}s+=txt(180,203,par?'u₁ = u₂ = u':'P = K₁(u − q) = K₂q');el.plot.innerHTML=svg(s,'直列と並列のばね');result(el,`合成剛性 K = <b>${fmt(r.k)} N/mm</b>、端の変位 u = <b>${fmt(r.u)} mm</b>。<br>${par?`共通の変位に対し、K₁ の力 ${fmt(r.f1)} N と K₂ の力 ${fmt(r.f2)} N を足すと ${fmt(v.P)} N。`:`中間の変位 q = <b>${fmt(r.q)} mm</b>。K₁ の変形 u−q = ${fmt(r.u-r.q)} mm、K₂ の変形 q = ${fmt(r.q)} mm。両方の力は ${fmt(v.P)} N。`}<br>${par?'K = K₁ + K₂。硬い側ほど大きい力を受け持ちます。':'1/K = 1/K₁ + 1/K₂。柔らかい側ほど大きく変形します。'}`);}};
 labs.gap={html:()=>layout(slider('d','2点の上下間隔 d（mm）',0,60,5,30)+slider('theta','剛体回転 θ（rad）',-.02,.02,.002,.01),'2点を結ぶ破線は位置関係で、ばねの軸ではありません。両点のCDは基本座標、CELAS は X 成分どうし、K = 120 N/mm。赤は回転を保つ外力で、ばねが節点に及ぼす力はその逆です。小回転の1次の式を使い、変位だけ50倍で描きます。'),draw(el,v){const dx=-v.d*v.theta,F=120*dx,M=-v.d*F,x=185,y=175,by=y-v.d*1.8,bx=x+dx*50;el.plot.innerHTML=svg(arrow(40,185,95,185,'el-axis')+txt(105,190,'X')+arrow(40,185,40,130,'el-axis')+txt(40,118,'Y')+line(x,y,x,by,'el-ghost')+line(x,y,bx,by)+circle(x,y)+circle(bx,by)+txt(x+14,y+18,'A')+txt(bx+14,by-14,'B')+arrow(bx,by,bx+Math.sign(F)*35,by)+arrow(x,y,x-Math.sign(F)*35,y)+txt(278,105,'d = '+fmt(v.d))+txt(175,220,'ΔuX = −dθ'),'剛体回転に抵抗してしまう離れたCELAS',245);result(el,`距離を保つ剛体回転なのに ΔuX = <b>${fmt(dx)} mm</b>。変位を保つ外力 fB = ${fmt(F)} N、fA = ${fmt(-F)} N。<br>外から加える偶力 M = <b>${fmt(M)} N·mm</b>、見かけの回転剛性 Kd² = ${fmt(120*v.d*v.d)} N·mm/rad。<br>${v.d===0?'d = 0 なら、この位置ずれに起因する抵抗はありません。':'d を2倍にすると、この不要な回転剛性は4倍になります。これは節点を結ぶ実物の軸ばねとは異なる挙動です。'}`);}};
 labs.direction={html:()=>layout(slider('angle','ブッシュの要素x軸 θ（°）',0,90,5,30)+slider('k2','K₂（N/mm）',0,200,10,20),'同じ位置にある2節点のうち一方を固定し、他方に基本X方向の相対変位0.5 mmを与えます。K₁ = 200 N/mm。要素x・y軸はCIDで定義した直交軸。図は相対変位と、それを保つ外力を示します。'),draw(el,v){const r=core.direction(200,v.k2,v.angle),a=rad(v.angle),c=Math.cos(a),s=Math.sin(a),ox=145,oy=142;el.plot.innerHTML=svg(arrow(ox,oy,ox+115,oy,'el-motion')+txt(280,oy+5,'uX')+arrow(ox,oy,ox+85*c,oy-85*s,'el-axis')+txt(ox+99*c,oy-99*s,'xₑ')+arrow(ox,oy,ox-65*s,oy-65*c,'el-axis')+txt(ox-80*s,oy-80*c,'yₑ')+circle(ox,oy)+arrow(ox,oy,ox+r.Fx*.7,oy-r.Fy*.7)+txt(280,36,'F = K u')+line(30,oy,320,oy,'el-ghost')+txt(320,oy+20,'X'),'CBUSHの向きと連成する反力');result(el,`基本座標で KXX = <b>${fmt(r.xx)}</b>、KXY = ${fmt(r.xy)}、KYY = ${fmt(r.yy)} N/mm。<br>必要な外力 FX = <b>${fmt(r.Fx)} N</b>、FY = <b>${fmt(r.Fy)} N</b>。Xだけ動かしても、軸が傾き K₁≠K₂ ならY方向の力が必要です。<br>K₁=K₂ にすると方向依存は消えます。CELAS の成分1はこの要素軸ではなく、各GRIDのCDで定まります。`);}};
 labs.kelvin={html:()=>layout(slider('c','粘性係数 c（N·s/mm）',0,20,1,5)+slider('f','変位を繰り返す周波数 f（Hz）',.5,5,.5,1),'変位 u = 0.5 sin(ωt) mm を強制し、K = 100 N/mm のばねと並列の粘性ダンパを動かします。実線は合力、破線はばねだけ。荷重を与えた系の共振応答ではありません。'),draw(el,v){const r=core.kelvin(100,v.c,v.f),ts=lin(0,2*Math.PI,121),mx=Math.hypot(r.elastic,r.viscous);el.plot.innerHTML=chart('kelvin',[['F',ts.map(t=>[.5*Math.sin(t),r.elastic*Math.sin(t)+r.viscous*Math.cos(t)])],['Ku',[[-.5,-50],[.5,50]]]],[-.6,.6],[-mx*1.15,mx*1.15],'u (mm)','F (N)');result(el,`ばね力の振幅 ${fmt(r.elastic)} N、粘性力の振幅 <b>${fmt(r.viscous)} N</b>。1周期で失うエネルギー（閉曲線の面積）= πcωU² = <b>${fmt(r.loss)} N·mm</b>。<br>静止して速度が0なら粘性力は0です。PBUSH のBとGEは別の指定で、同じ数値を入れて同じ減衰になるわけではありません。`);}};
 labs.thickness={html:()=>layout(slider('t','板厚 t（mm）',1,8,.5,2)+select('load','図に表示する変形',[['bend','端モーメントによる曲げ'],['membrane','面内の引張']],'bend'),'長さ100 mm・幅100 mmの細帯をE = 70,000 MPaで比較。面内荷重P = 700 Nと端モーメントM = 100 N·mmは別々に作用させます。横方向に自由に変形できる細帯の梁理論であり、全周を拘束した板の解ではありません。変形と厚さは見えるように拡大しています。'),draw(el,v){const t=v.t,E=70000,b=100,L=100,I=b*t**3/12,u=700*L/(E*b*t),w=100*L*L/(2*E*I),ps=cube(7,4,t*.09),transform=(x,y,z)=>v.load==='bend'?[x+z*3.6*x/(49*t**3),y,z-1.8*x*x/(49*t**3)]:[x+x*.15/t,y*(1-.015/t),z*(1-.015/t)];el.plot.innerHTML=scene([...ghost3(ps),...strip3(7,4,t*.09,transform),...axes3([0,-2.7,-.6],1),...(v.load==='membrane'?a3([7.1,0,0],[8.6,0,0],'P'):[...a3([7,0,.65],[8.2,0,.65],'F'),...a3([7,0,-.65],[5.8,0,-.65],'−F')])],'板厚による変形の違い');result(el,`t = 2 mmを基準に、膜剛性 Et は <b>${fmt(t/2)}倍</b>、曲げ剛性 EI は <b>${fmt((t/2)**3)}倍</b>、質量は ${fmt(t/2)}倍。<br>引張時 u = ${fmt(u)} mm、曲げ時の先端たわみ w = <b>${fmt(w)} mm</b>。曲げ表面応力は ${fmt(6*100/(b*t*t))} MPa。<br>板厚2倍で、同じ力の伸びは1/2、同じモーメントのたわみは1/8、曲げ応力は1/4になります。`);}};
 labs.surfaces={html:()=>layout(slider('N','膜力 Nx（N/mm）',-150,150,10,100)+slider('M','曲げの合力 M*（N·mm/mm）',-200,200,10,100)+select('normal','節点順と法線',[['up','法線は上向き'],['down','節点順を逆にして下向き']],'up'),'板厚4 mm。物理的な上面A・下面Bと荷重は固定し、法線だけ切り替えます。M* = ∫zσx dz と定義し、正なら上面Aが引張。この教材のM*を、F06の曲げモーメント列の符号と無条件に同一視しないでください。'),draw(el,v){const r=core.surface(v.N,v.M,4),sg=v.normal==='up'?1:-1,scale=105/Math.max(Math.abs(r.top),Math.abs(r.bottom),1),zx=220,yt=65,yb=165;let s=`<rect x="32" y="${yt}" width="68" height="${yb-yt}" class="el-fill"/>`+line(25,115,340,115,'el-ghost')+txt(60,45,'A')+txt(60,188,'B')+arrow(115,115,115,115-65*sg,'el-axis')+txt(115,115-75*sg,'zₑ')+txt(32,yt+16,sg>0?'Z2':'Z1','start')+txt(32,yb-10,sg>0?'Z1':'Z2','start')+line(zx,40,zx,190,'el-grid')+line(zx+r.top*scale,yt,zx+r.bottom*scale,yb)+arrow(zx,yt,zx+r.top*scale,yt)+arrow(zx,yb,zx+r.bottom*scale,yb)+txt(zx+r.top*scale,yt-8,fmt(r.top))+txt(zx+r.bottom*scale,yb+20,fmt(r.bottom))+txt(270,215,'σx (MPa)');el.plot.innerHTML=svg(s,'法線と物理的な表裏の応力');result(el,`膜応力 Nx/t = ${fmt(r.mean)} MPa、曲げ寄与 ±6M*/t² = ±${fmt(r.bend)} MPa。<br>上面Aは <b>${fmt(r.top)} MPa</b>、下面Bは <b>${fmt(r.bottom)} MPa</b>。${sg<0?'法線を反転したので、AはZ1側、BはZ2側です。':'AはZ2側、BはZ1側です。'}<br>荷重を変えていないので物理的な応力は変わりません。比較するのは「Z1の列どうし」ではなく、同じ物理的な面です。`);}};
 labs.material={html:()=>layout(select('kind','面内材料',[['ortho','直交異方性：E₁ = 140 GPa、E₂ = 10 GPa'],['iso','等方性：E = 70 GPa']],'ortho')+slider('angle','材料1軸 θ（°）',0,90,5,30),'基本X方向に100 MPaの一軸引張。異方性はG₁₂ = 5 GPa、ν₁₂ = 0.3。等方性はν = 0.3。青の1・2が材料軸、赤が外力、破線が変形前、変形は20倍。材料軸を回すことと、結果の表示軸だけを回すことを区別します。'),draw(el,v){const r=core.material(v.angle,v.kind==='iso'),a=rad(v.angle),c=Math.cos(a),s=Math.sin(a),cx=175,cy=125,ps=[[-100,-50],[100,-50],[100,50],[-100,50]],pts=ps.map(([x,y])=>[cx+x*(1+20*r.ex)+y*10*r.gxy,cy-y*(1+20*r.ey)-x*10*r.gxy]);el.plot.innerHTML=svg(`<rect x="75" y="75" width="200" height="100" class="el-ghost"/><polygon class="el-fill" points="${pts.map(p=>p.join(',')).join(' ')}"/>`+arrow(cx,cy,cx+78*c,cy-78*s,'el-axis')+txt(cx+90*c,cy-90*s,'1')+arrow(cx,cy,cx-50*s,cy-50*c,'el-axis')+txt(cx-65*s,cy-65*c,'2')+arrow(55,125,18,125)+arrow(295,125,342,125)+txt(180,32,'σX = 100 MPa')+txt(180,218,'X →'),'材料軸と変形');result(el,`材料軸で σ₁ = ${fmt(r.s1)}、σ₂ = ${fmt(r.s2)}、τ₁₂ = ${fmt(r.tau)} MPa。<br>荷重方向のひずみ εX = <b>${fmt(r.ex)}</b>、見かけの縦弾性係数 100/εX = <b>${fmt(100/r.ex/1000)} GPa</b>。<br>${v.kind==='iso'?'等方性では軸を回しても変形は同じ。応力成分の数字だけが変わります。':'異方性では材料の向き自体を変えると変形も変わります。THETA/MCID は構造の硬い向きを決める入力です。'}`);}};
 labs.quad={html:()=>layout(slider('x','G3 の x',-1.4,1.6,.1,1)+slider('y','G3 の y',-1.4,1.6,.1,1),'四角形の4節点補間で、基準の正方形を実際の形へ写す計算。細線は自然座標の等間隔線、点は2×2のGauss点です。表示のdet Jはこの幾何写像の値で、MSCのGEOMCHECKの個別判定値ではありません。'),draw(el,v){const q=core.quad(v.x,v.y),P=([x,y])=>[180+x*65,128-y*65];let s='';for(const u of lin(-1,1,9))for(const reverse of [false,true]){const pts=lin(-1,1,31).map(w=>P(q.map(...(reverse?[w,u]:[u,w]))));s+=`<polyline class="el-grid" points="${pts.map(p=>p.join(',')).join(' ')}"/>`;}s+=`<polygon class="el-edge" points="${q.ps.map(P).map(p=>p.join(',')).join(' ')}"/>`;q.ps.forEach((p,i)=>{const [x,y]=P(p);s+=circle(x,y)+txt(x+(i===0||i===3?-14:14),y+(i<2?19:-12),'G'+(i+1));});for(const r of [-1/Math.sqrt(3),1/Math.sqrt(3)])for(const t of [-1/Math.sqrt(3),1/Math.sqrt(3)]){const [x,y]=P(q.map(r,t));s+=circle(x,y,3,'el-node-mid');}el.plot.innerHTML=svg(s,'四角形要素の写像とつぶれ',260);result(el,`四隅での最小 det J = <b>${fmt(q.min)}</b>。中心 = ${fmt(q.jac(0,0))}。<br>${q.min<=0?'<span class="el-warn">つぶれ、または局所的な反転があります。節点順・形状を修正します。中心の値だけでは見逃すことがあります。</span>':'この形は内部で反転していません。ただし正のdet Jだけで精度は保証されません。ゆがみ・細長さ・解の変化を別々に確認します。'}`);}};
 labs.sandwich={html:()=>layout(slider('c','芯材の厚さ c（mm）',0,30,1,10),'上下の表皮は各1 mm、E = 70 GPa、密度2,700 kg/m³。芯材はE = 100 MPa、密度100 kg/m³。同じ曲率で一体に曲がり、滑り・はく離がない断面の計算です。曲げ剛性だけを比較し、柔らかい芯材の横せん断によるたわみは含めません。'),draw(el,v){const r=core.sandwich(v.c),b=core.sandwich(0),h=(v.c+2)*4,y=125-h/2;el.plot.innerHTML=svg(`<rect x="55" y="${y}" width="250" height="${h}" class="el-soft"/><rect x="55" y="${y}" width="250" height="4" class="el-fill"/><rect x="55" y="${y+h-4}" width="250" height="4" class="el-fill"/>`+line(40,125,320,125,'el-ghost')+txt(180,y-13,'tƒ = 1 mm')+txt(180,130,'c = '+v.c+' mm')+txt(180,y+h+23,'tƒ = 1 mm'),'サンドイッチ断面の表皮の距離',240);result(el,`単位幅の曲げ剛性 B = ΣEi(Ii + Ai zi²) = <b>${fmt(r.B)} N·mm</b>。芯材なしの <b>${fmt(r.B/b.B)}倍</b>。<br>面積あたり質量は ${fmt(r.mass)} kg/m²（${fmt(r.mass/b.mass)}倍）。<br>表皮を中立面から離すと Ai zi² が効きます。質量を少し増やして曲げ剛性を大きくできますが、芯材のせん断変形や接着の評価は別に必要です。`);}};
 labs.drilling={html:()=>layout(select('kind','回転の与え方',[['rigid','節点の並進を伴う剛体回転'],['drill','節点位置は固定し、法線回転だけ']],'rigid')+slider('theta','θ（°）',-15,15,1,10),'中央面を正面から見ます。大きな回転は見やすさのためで、式は小回転の説明です。これは標準シェルの自由度の意味を示す図で、K6ROTの人工剛性を数値再現したものではありません。'),draw(el,v){const a=rad(v.theta),ps=[[-90,-55],[90,-55],[90,55],[-90,55]],P=([x,y])=>[180+x,120-y],q=ps.map(([x,y])=>v.kind==='rigid'?[x*Math.cos(a)-y*Math.sin(a),x*Math.sin(a)+y*Math.cos(a)]:[x,y]);let s=`<polygon class="el-ghost" points="${ps.map(P).map(p=>p.join(',')).join(' ')}"/><polygon class="el-fill" points="${q.map(P).map(p=>p.join(',')).join(' ')}"/>`;q.forEach((p,i)=>{const [x,y]=P(p);s+=circle(x,y)+txt(x+(i===0||i===3?-20:20),y,'G'+(i+1));if(v.kind==='rigid'){const [u,w]=P(ps[i]);s+=arrow(u,w,x,y,'el-motion');}else{s+=`<path d="M${x+14},${y} A14,14 0 1 0 ${x},${y+14}" class="el-motion"/>`+arrow(x-5,y+14,x+2,y+14,'el-motion');}});s+=txt(180,220,v.kind==='rigid'?'uX = −θY, uY = θX':'uX = uY = 0, θz ≠ 0');el.plot.innerHTML=svg(s,'剛体回転と法線まわりの独立回転',240);result(el,v.kind==='rigid'?'剛体回転では位置も回ります。小回転のひずみ εX = ∂uX/∂X = 0、εY = 0、γXY = ∂uX/∂Y + ∂uY/∂X = −θ+θ = 0。変形エネルギーを生みません。':'節点位置を変えず θz だけ回しても、古典的な膜の変位場は変わりません。法線回転に物理的な剛性があるか、数値安定化なのかを区別します。K6ROTを接合部の実際のねじり剛性と考えないでください。');}};
 labs.poisson={html:()=>layout(slider('nu','ポアソン比 ν',0,.49,.01,.3)+select('held','横方向の条件',[['free','横へ自由に収縮する'],['held','横2方向の変位を全体で止める']],'free'),'長さ100 mm、20 mm角の直方体に軸応力10 MPa。E = 2,000 MPa。端部近傍を除く一様な応力・ひずみ場の比較です。横拘束は端面だけの固定ではなく、εy = εz = 0 の条件。破線が変形前、変形は40倍です。'),draw(el,v){const r=core.poisson(v.nu,v.held==='held'),ps=cube(),q=ps.map(([x,y,z])=>[x*(1+40*r.ex),y*(1+40*r.ey),z*(1+40*r.ey)]),items=[...ghost3(ps),...poly3(q),...axes3([0,-1.7,-1.3],1),...a3([5.1,0,0],[6.6,0,0],'σx'),...a3([-.1,0,0],[-1.3,0,0])];if(v.held==='held')items.push(...a3([2,1.1,0],[2,2,0],'σy'),...a3([2,0,1.1],[2,0,2],'σz'));el.plot.innerHTML=scene(items,'横収縮と拘束による見かけの剛性');result(el,`軸ひずみ εx = <b>${fmt(r.ex)}</b>、伸び u = ${fmt(100*r.ex)} mm。横ひずみ εy = εz = ${fmt(r.ey)}。<br>軸方向の見かけの剛性は E の <b>${fmt(r.ratio)}倍</b>、横応力 σy = σz = ${fmt(r.sy)} MPa。<br>${v.held==='held'?'拘束した横方向にも引張反力が必要です。νが0.5に近づくと、体積を変えにくい材料を横に止めた影響が大きくなります。':'横へ縮めるので、軸方向はσx = Eεxです。Eを変更しなくても、横拘束を追加すると別の結果になります。'}`);}};
 labs.interpolation={html:()=>layout(slider('n','辺を分割する数 n',1,12,1,1)+select('order','辺上の補間',[['linear','端点だけ：1次'],['quadratic','中間点も使う：2次']],'linear'),'仮定した変位場 u(x) = 1 mm × (x/100 mm)² を、節点値から再現する実験です。上が変位、下がその微分であるひずみ。実線は補間、破線は与えた関数。要素剛性を解いた結果や、特定の荷重のMSC実行結果ではありません。'),draw(el,v){const quad=v.order==='quadratic',xs=lin(0,1,121),us=xs.map(x=>[x,core.interpolate(x,v.n,quad).u]),strain=[];if(quad)xs.forEach(x=>strain.push([x,2*x]));else for(let i=0;i<v.n;i++)strain.push([i/v.n,(2*i+1)/v.n],[(i+1)/v.n,(2*i+1)/v.n]);el.plot.innerHTML=chart('interp-u',[['uₕ',us],['u',xs.map(x=>[x,x*x])]], [0,1],[0,1],'x/L','u/δ')+chart('interp-e',[['εₕ',strain],['ε',xs.map(x=>[x,2*x])]], [0,1],[0,2],'x/L','ε/(δ/L)');result(el,`最大変位誤差は <b>${quad?'0':fmt(1/(4*v.n*v.n))} mm</b>。${quad?'この2次関数は、中間節点を含む2次補間で正確に表せます。':'分割数2倍で変位誤差は1/4。ひずみは区間ごとに一定で、微分すると粗さが目立ちます。'}<br>4節点CTETRAでは要素内の変位が1次、ひずみが一定です。10節点化や細分化は変化するひずみを表す助けになりますが、曲面の中間節点位置・積分・形状品質も確認します。`);}};
 labs.couple={html:()=>layout(slider('h','上下の節点間隔 h（mm）',10,80,5,40)+select('n','力を配る節点数',[['2','上下に1点ずつ'],['4','上下に2点ずつ'],['8','上下に4点ずつ']],'4'),'端面に曲げモーメントMy = 1,000 N·mmを、並進の力の偶力として伝えます。上が＋z、力はx方向。中央の点に回転拘束だけを置く場合とは異なります。剛な断面を仮定した対称な力の配分例で、局所応力の分布を求めたものではありません。'),draw(el,v){const n=+v.n,r=core.couple(1000,v.h,n),H=v.h/20,ps=cube(3,3,H),items=poly3(ps);r.forEach((o,i)=>{const j=i%(n/2),y=n===2?0:-1.2+2.4*j/(n/2-1),z=o.z/20;items.push({k:'dot',p:[[3,y,z]],c:'b3-node'},...a3([3,y,z],[3+Math.sign(o.F)*1.25,y,z],i===0?'F':''));});items.push(...axes3([0,-2,-H/2-.5],1));el.plot.innerHTML=scene(items,'並進自由度へ伝える曲げモーメント');result(el,`各節点の力 Fi = M zi / Σzj²。上の各点 <b>+${fmt(r[0].F)} N</b>、下の各点 ${fmt(-r[0].F)} N。<br>ΣFi = <b>${fmt(r.reduce((s,o)=>s+o.F,0))} N</b>、ΣziFi = <b>${fmt(r.reduce((s,o)=>s+o.F*o.z,0))} N·mm</b>。<br>間隔hを半分にすると必要な力は2倍。梁のモーメントをソリッドへ渡すには、このように複数の並進自由度へ伝わる経路が必要です。`);}};
 labs.tetra={html:()=>layout(slider('h','高さ / 基準辺長',.05,1.5,.05,1)+select('order','節点の順番',[['normal','1 → 2 → 3 → 4'],['reverse','2と3の番号を交換']],'normal'),'底面の直角三角形の辺は各100 mm、高さ100h mm。直線辺を持つ四面体の J = [x₂−x₁, x₃−x₁, x₄−x₁] を計算します。番号を交換しても形は同じですが、符号付きの写像が反転します。'),draw(el,v){const reverse=v.order==='reverse',r=core.tetra(v.h,reverse),ps=[[0,0,0],[3,0,0],[0,3,0],[.8,.8,v.h*3]],faces=[[0,2,1],[0,1,3],[1,2,3],[2,0,3]],items=[...poly3(ps,faces),...[[0,2],[1,2],[2,3]].map(([a,b])=>({k:'line',p:[ps[a],ps[b]],c:'b3-ghost'}))];ps.forEach((p,i)=>items.push({k:'dot',p:[p],c:'b3-node'},{k:'text',p:[p],s:'G'+(reverse?(i===1?3:i===2?2:i+1):i+1),dx:i===2?-18:7,dy:i===3?-8:15}));el.plot.innerHTML=scene(items,'四面体の高さと符号付き体積');result(el,`det J = <b>${fmt(r.det)} mm³</b>、幾何学的な体積 |det J|/6 = ${fmt(r.volume)} mm³。<br>${reverse?'<span class="el-warn">節点の順番を入れ替えて符号が負になりました。体積の絶対値だけを見ても反転は分かりません。</span>':`上端だけz方向に1 mm動かす補間なら εzz = 1/(100h) = ${fmt(r.gradient)}。高さが小さいほど同じ節点変位差から大きい勾配が生じます。`}<br>正の体積だけでは十分ではありません。つぶれた要素、荷重の集中位置、解の変化を確認します。`);}};
 labs.pressure={html:()=>layout(slider('p','全方向の圧縮 p（MPa）',0,100,5,50)+slider('tau','せん断応力 τxy（MPa）',0,100,5,20),'一様な3次元応力：σx = σy = σz = −p、τxy = τ。E = 70 GPa、ν = 0.3。赤の法線方向の力が圧縮、せん断で形が斜めになります。破線は変形前。変形は100倍です。'),draw(el,v){const r=core.pressure(v.p,v.tau),ps=cube(3,3,3),q=ps.map(([x,y,z])=>[(x-1.5)*(1+100*r.ex)+y*r.gamma*50+1.5,y*(1+100*r.ex)+(x-1.5)*r.gamma*50,z*(1+100*r.ex)]),items=[...ghost3(ps),...poly3(q)];if(v.p)items.push(...a3([4.4,0,0],[3.2,0,0],'p'),...a3([1.5,-2.8,0],[1.5,-1.7,0]),...a3([1.5,0,2.8],[1.5,0,1.7]));if(v.tau)items.push(...a3([1,1.9,.7],[2.5,1.9,.7],'τ'),...a3([2,-1.9,.7],[.5,-1.9,.7]));items.push(...axes3([-.5,-2,-2],1));el.plot.innerHTML=scene(items,'体積変形とせん断変形');result(el,`体積ひずみ εv = −p/K = <b>${fmt(r.ev)}</b>。せん断ひずみ γxy = τ/G = ${fmt(r.gamma)}。<br>von Mises応力は <b>${fmt(r.vm)} MPa</b>、主応力は ${r.principal.map(x=>fmt(x)).join('、')} MPa。<br>pだけを増やしてもvon Mises値は変わりません。全方向圧縮を無視してよいという意味ではなく、圧力に敏感な破壊・材料には別の評価が必要です。`);}};
 labs.cylinder={html:()=>layout(slider('ratio','外半径 / 内半径 b/a',1.2,4,.1,2.5)+select('end','軸方向の条件',[['open','軸応力なし：σz = 0'],['closed','閉じた端の圧力も受ける']],'open'),'内半径a = 20 mm、内圧p = 10 MPa、外圧0。十分長い厚肉円筒のLamé解。端部・穴・接触の近くを表す解ではありません。横軸は肉厚内の半径。軸対称モデルでも半径・周・軸方向の3成分を読む必要があります。'),draw(el,v){const a=20,b=a*v.ratio,closed=v.end==='closed',rs=lin(a,b),wall=rs.map(x=>core.cylinder(x,b,a,10,closed)),q=wall[0],R=74,r=R/v.ratio,cx=180,cy=90;let drawing=`<circle cx="${cx}" cy="${cy}" r="${R}" class="el-fill"/><circle cx="${cx}" cy="${cy}" r="${r}" fill="white" stroke="#456882"/>`;for(const th of [0,45,90,135,180,225,270,315]){const t=rad(th);drawing+=arrow(cx+Math.cos(t)*(r-16),cy+Math.sin(t)*(r-16),cx+Math.cos(t)*(r-2),cy+Math.sin(t)*(r-2));}drawing+=txt(180,95,'p')+line(cx,cy,cx+R,cy,'el-ghost')+txt(cx+r+8,cy+18,'a')+txt(cx+R+12,cy+4,'b');el.plot.innerHTML=svg(drawing,'厚肉円筒の内圧と肉厚',180)+chart('cylinder',[['σr',rs.map((r,i)=>[r,wall[i].sr])],['σθ',rs.map((r,i)=>[r,wall[i].st])],['σz',rs.map((r,i)=>[r,wall[i].sz])]], [a,b],[-10,q.st*1.1],'r (mm)','σ (MPa)');result(el,`内面で σr = <b>${fmt(q.sr)} MPa</b>、σθ = <b>${fmt(q.st)} MPa</b>、σz = ${fmt(q.sz)} MPa。外面のσr = 0。<br>薄肉近似 pa/(b−a) = ${fmt(10*a/(b-a))} MPa に対し、内面の周応力は <b>${fmt(q.st/(10*a/(b-a)))}倍</b>。<br>厚肉では板厚方向の応力を省略できません。全周一様なら軸対称、周方向に変わる荷重や穴があるなら3次元でモデル化します。`);}};

 labs.hexa={html:()=>layout(select('order','節点',[['8','隅の8節点'],['20','辺の中間も含む20節点']],'8')+slider('skew','上面のずれ / 高さ',0,.8,.1,0),'塗りつぶした点は隅、白抜きは辺の中間点です。奥の辺は破線、隠れたG4は点線の輪郭で示します。上面を横へずらしても体積は同じですが、辺の角度や形状は変わります。中間点の番号は省き、配置を確認する図にしています。'),draw(el,v){const ps=cube(3,3,3).map(([x,y,z])=>[x+(z+1.5)*v.skew,y,z]),items=[...poly3(ps),...[0,2,7].map(i=>({k:'line',p:[ps[3],ps[i]],c:'b3-ghost'}))],edges=[[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]];ps.forEach((p,i)=>items.push({k:'dot',p:[p],c:i===3?'el-node-hidden':'b3-node'},{k:'text',p:[p],s:'G'+(i+1),dx:i===3||i===7?-19:7,dy:i<4?16:-8}));if(v.order==='20')for(const [a,b] of edges)items.push({k:'dot',p:[avg([ps[a],ps[b]])],c:'el-node-mid',r:4});el.plot.innerHTML=scene(items,'六面体の隅と中間節点',275);result(el,`節点数は <b>${v.order}</b>、変位の成分数は ${+v.order*3}（拘束・接続前の数え方）。<br>${v.order==='20'?'中間点は変位の2次の変化や曲辺を表すための自由度です。点を追加するだけで、どんな形でも高精度になるわけではありません。':'隅だけの三重1次補間では、要素内の表せる変位分布に制限があります。曲げや局所的な変化は細分化や2次要素と比較します。'}<br>体積が同じでもゆがみが大きいと写像と精度に影響します。節点順・形状・結果の収束を組み合わせて確認します。`);}};
 function connect(root){for(const fig of root.querySelectorAll('[data-element-lab]')){if(fig.dataset.elReady)continue;const lab=labs[fig.dataset.elementLab];if(!lab)continue;fig.dataset.elReady='1';fig.classList.add('element-figure','theory-lab','element-lab');fig.innerHTML=lab.html();const el={plot:fig.querySelector('.el-plot'),read:fig.querySelector('.theory-lab-readout'),inputs:{},out:{}};for(const e of fig.querySelectorAll('[data-el-input]'))el.inputs[e.dataset.elInput]=e;for(const e of fig.querySelectorAll('[data-el-out]'))el.out[e.dataset.elOut]=e;const draw=()=>{const v=vals(el);outputs(el,v);lab.draw(el,v);};fig.addEventListener('input',draw);fig.addEventListener('change',draw);draw();}}
 window.ElementLabs={core,labs,connect};
 if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',()=>connect(document));
})();
